+.matrix-table th, .matrix-table td {
+  padding: 1.25rem 1.75rem;
+  border-bottom: 1px solid rgba(212, 175, 55, 0.08);
+}
+
+.matrix-table th {
+  background: rgba(14, 17, 24, 0.9);
+  font-family: var(--font-mono);
+  font-size: 0.75rem;
+  letter-spacing: 0.2em;
+  text-transform: uppercase;
+  color: var(--gold-prime);
+}
+
+.matrix-table td {
+  font-family: var(--font-serif);
+  font-size: 1.05rem;
+  color: var(--text-prime);
+}
+
+.matrix-table tr:last-child td {
+  border-bottom: none;
+}
+
+.matrix-table tr:hover td {
+  background: rgba(212, 175, 55, 0.03);
+}
+
+.matrix-realm-tag {
+  font-family: var(--font-display);
+  font-weight: 700;
+  color: var(--gold-light);
+}
+
+/* ═══════════════════════════════════════════════════════════════════════════
+   THE PRIVATE DOSSIER / RESERVATION DIALOG
+   ═══════════════════════════════════════════════════════════════════════════ */
+dialog.elysian-dialog {
+  border: 1px solid var(--border-bright);
+  background: #080a0f;
+  color: var(--text-prime);
+  border-radius: var(--radius-lg);
+  padding: clamp(2rem, 5vw, 3.5rem);
+  max-width: 680px;
+  width: 90vw;
+  margin: auto;
+  box-shadow: 0 30px 90px rgba(0, 0, 0, 0.9), 0 0 40px var(--gold-glow);
+  z-index: 10000;
+  overflow-y: auto;
+  max-height: 90vh;
+}
+
+dialog.elysian-dialog::backdrop {
+  background: rgba(3, 4, 7, 0.85);
+  backdrop-filter: blur(12px);
+}
+
+.dialog-header {
+  display: flex;
+  justify-content: space-between;
+  align-items: flex-start;
+  margin-bottom: 2rem;
+  border-bottom: 1px solid var(--border-subtle);
+  padding-bottom: 1.25rem;
+}
+
+.dialog-title {
+  font-family: var(--font-display);
+  font-size: clamp(1.6rem, 3vw, 2.2rem);
+  color: var(--gold-light);
+}
+
+.btn-dialog-close {
+  background: none;
+  border: 1px solid var(--border-subtle);
+  color: var(--text-muted);
+  width: 36px;
+  height: 36px;
+  border-radius: 50%;
+  cursor: pointer;
+  font-size: 1.25rem;
+  display: grid;
+  place-items: center;
+  transition: all 0.2s ease;
+}
+
+.btn-dialog-close:hover {
+  border-color: var(--gold-prime);
+  color: var(--gold-light);
+}
+
+.dossier-form {
+  display: flex;
+  flex-direction: column;
+  gap: 1.5rem;
+}
+
+.form-field {
+  display: flex;
+  flex-direction: column;
+  gap: 0.5rem;
+}
+
+.form-label {
+  font-family: var(--font-mono);
+  font-size: 0.75rem;
+  letter-spacing: 0.15em;
+  text-transform: uppercase;
+  color: var(--gold-prime);
+}
+
+.form-input, .form-select, .form-textarea {
+  background: rgba(255, 255, 255, 0.04);
+  border: 1px solid var(--border-subtle);
+  padding: 0.85rem 1.2rem;
+  border-radius: var(--radius-sm);
+  color: var(--text-prime);
+  font-family: var(--font-sans);
+  font-size: 0.95rem;
+  outline: none;
+  transition: border-color 0.3s ease;
+}
+
+.form-input:focus, .form-select:focus, .form-textarea:focus {
+  border-color: var(--gold-prime);
+}
+
+/* Interactive Wax Seal Stamp */
+.wax-seal-wrapper {
+  display: flex;
+  flex-direction: column;
+  align-items: center;
+  gap: 1rem;
+  padding: 1.5rem;
+  background: rgba(255, 255, 255, 0.02);
+  border: 1px dashed var(--border-mid);
+  border-radius: var(--radius-md);
+  margin-top: 0.5rem;
+  text-align: center;
+}
+
+.wax-seal-btn {
+  width: 80px;
+  height: 80px;
+  border-radius: 50%;
+  background: radial-gradient(circle at 30% 30%, #ffd700, #b8860b, #6b4e07);
+  border: 2px solid #fff5cc;
+  box-shadow: 0 6px 20px rgba(212, 175, 55, 0.4);
+  cursor: pointer;
+  display: grid;
+  place-items: center;
+  transition: transform 0.2s ease, box-shadow 0.2s ease;
+}
+
+.wax-seal-btn:hover {
+  transform: scale(1.08);
+  box-shadow: 0 10px 30px rgba(212, 175, 55, 0.6);
+}
+
+.wax-seal-btn.sealed {
+  animation: sealPress 0.5s ease-out;
+}
+
+@keyframes sealPress {
+  0% { transform: scale(1.2); }
+  50% { transform: scale(0.9); }
+  100% { transform: scale(1); }
+}
+
+.confirmation-card {
+  padding: 1.5rem;
+  border-radius: var(--radius-md);
+  background: rgba(212, 175, 55, 0.08);
+  border: 1px solid var(--border-bright);
+  text-align: center;
+  display: none;
+}
+
+.confirmation-card.show {
+  display: block;
+}
+
+/* ═══════════════════════════════════════════════════════════════════════════
+   FOOTER & CURATION COLOPHON
+   ═══════════════════════════════════════════════════════════════════════════ */
+.colophon-footer {
+  position: relative;
+  background: var(--bg-deep);
+  border-top: 1px solid var(--border-subtle);
+  padding: clamp(4rem, 8vw, 6rem) clamp(1.25rem, 5vw, 4rem) 3rem;
+  z-index: 10;
+}
+
+.footer-grid {
+  display: grid;
+  grid-template-columns: 2fr repeat(3, 1fr);
+  gap: clamp(2rem, 4vw, 4rem);
+  max-width: var(--container-max);
+  margin: 0 auto 4rem;
+}
+
+@media (max-width: 900px) {
+  .footer-grid {
+    grid-template-columns: 1fr 1fr;
+  }
+}
+
+@media (max-width: 550px) {
+  .footer-grid {
+    grid-template-columns: 1fr;
+  }
+}
+
+.footer-brand .brand-wordmark {
+  margin-bottom: 1rem;
+}
+
+.footer-tagline {
+  font-family: var(--font-serif);
+  font-style: italic;
+  font-size: 1.15rem;
+  color: var(--text-muted);
+  max-width: 320px;
+  line-height: 1.6;
+}
+
+.footer-column-title {
+  font-family: var(--font-mono);
+  font-size: 0.75rem;
+  letter-spacing: 0.2em;
+  text-transform: uppercase;
+  color: var(--gold-prime);
+  margin-bottom: 1.25rem;
+}
+
+.footer-links {
+  list-style: none;
+  display: flex;
+  flex-direction: column;
+  gap: 0.75rem;
+}
+
+.footer-links a {
+  font-family: var(--font-sans);
+  font-size: 0.85rem;
+  color: var(--text-muted);
+  text-decoration: none;
+  transition: color 0.25s ease;
+}
+
+.footer-links a:hover {
+  color: var(--gold-light);
+}
+
+.footer-bottom {
+  max-width: var(--container-max);
+  margin: 0 auto;
+  border-top: 1px solid rgba(255, 255, 255, 0.05);
+  padding-top: 2rem;
+  display: flex;
+  justify-content: space-between;
+  align-items: center;
+  flex-wrap: wrap;
+  gap: 1rem;
+}
+
+.footer-copyright {
+  font-family: var(--font-sans);
+  font-size: 0.75rem;
+  color: var(--text-dim);
+}
+
+.footer-model-badge {
+  font-family: var(--font-mono);
+  font-size: 0.7rem;
+  color: var(--gold-prime);
+  letter-spacing: 0.1em;
+}
+
+/* ═══════════════════════════════════════════════════════════════════════════
+   RESPONSIVE & ACCESSIBILITY OVERRIDES
+   ═══════════════════════════════════════════════════════════════════════════ */
+@media (max-width: 25rem) {
+  :root {
+    --header-height: 72px;
+  }
+  .primary-title-h1 {
+    font-size: 2.2rem;
+  }
+  .manifesto-stats {
+    grid-template-columns: 1fr;
+  }
+}
+
+@media (prefers-reduced-motion: reduce) {
+  *, *::before, *::after {
+    animation-duration: 0.01ms !important;
+    animation-iteration-count: 1 !important;
+    transition-duration: 0.01ms !important;
+    scroll-behavior: auto !important;
+  }
+  #celestialCanvas {
+    display: none;
+  }
+}

success.afterFullFileContent:
/* ═══════════════════════════════════════════════════════════════════════════
   ELYSIAN — HIGH LUXURY EDITORIAL EXPERIENCE
   ═══════════════════════════════════════════════════════════════════════════ */

:root {
  /* Color Palette - Nocturne Default */
  --bg-prime: #07080c;
  --bg-deep: #030407;
  --bg-surface: #0e1118;
  --bg-surface-elevated: #151a24;
  --bg-glass: rgba(14, 17, 24, 0.7);
  --bg-glass-card: rgba(18, 22, 31, 0.6);
  --border-subtle: rgba(212, 175, 55, 0.15);
  --border-mid: rgba(212, 175, 55, 0.35);
  --border-bright: rgba(244, 228, 186, 0.75);

  --gold-prime: #d4af37;
  --gold-light: #f4e4ba;
  --gold-dark: #8c6d1d;
  --gold-gradient: linear-gradient(135deg, #f4e4ba 0%, #d4af37 50%, #aa820a 100%);
  --gold-glow: rgba(212, 175, 55, 0.25);

  --text-prime: #f7f5f0;
  --text-muted: #aba69a;
  --text-dim: #6d6a62;
  --text-highlight: #ffffff;

  --accent-cyan: #5eead4;
  --accent-rose: #f472b6;
  --accent-purple: #c084fc;
  --accent-amber: #fbbf24;

  /* Typography */
  --font-display: 'Cinzel Decorative', 'Cinzel', 'Playfair Display', serif;
  --font-serif: 'Cormorant Garamond', 'Italiana', 'Georgia', serif;
  --font-sans: 'Plus Jakarta Sans', system-ui, -apple-system, sans-serif;
  --font-mono: 'Space Mono', 'SF Mono', monospace;

  /* Transitions & Radii */
  --ease-out-expo: cubic-bezier(0.16, 1, 0.3, 1);
  --ease-in-out-circ: cubic-bezier(0.85, 0, 0.15, 1);
  --radius-sm: 4px;
  --radius-md: 10px;
  --radius-lg: 24px;
  --radius-full: 9999px;

  --container-max: 1440px;
  --header-height: 84px;
}

/* Atmospheric Variations */
[data-theme="aurora"] {
  --bg-prime: #0f0b14;
  --bg-deep: #08050c;
  --bg-surface: #1a1222;
  --bg-surface-elevated: #261b32;
  --border-subtle: rgba(244, 114, 182, 0.2);
  --border-mid: rgba(244, 114, 182, 0.4);
  --gold-prime: #f0a8d0;
  --gold-light: #fce7f3;
  --gold-dark: #a21caf;
  --gold-glow: rgba(244, 114, 182, 0.25);
  --gold-gradient: linear-gradient(135deg, #fce7f3 0%, #f472b6 50%, #c084fc 100%);
  --text-prime: #faf5ff;
}

[data-theme="meridian"] {
  --bg-prime: #121316;
  --bg-deep: #0a0b0d;
  --bg-surface: #1e2025;
  --bg-surface-elevated: #2a2c34;
  --border-subtle: rgba(201, 160, 80, 0.2);
  --border-mid: rgba(201, 160, 80, 0.4);
  --gold-prime: #c9a050;
  --gold-light: #fef3c7;
  --gold-dark: #78350f;
  --gold-glow: rgba(201, 160, 80, 0.25);
  --gold-gradient: linear-gradient(135deg, #fef3c7 0%, #c9a050 50%, #854d0e 100%);
  --text-prime: #f8fafc;
}

[data-theme="crepuscule"] {
  --bg-prime: #11090c;
  --bg-deep: #070305;
  --bg-surface: #201017;
  --bg-surface-elevated: #2f1923;
  --border-subtle: rgba(207, 117, 80, 0.2);
  --border-mid: rgba(207, 117, 80, 0.4);
  --gold-prime: #e07a5f;
  --gold-light: #fed7aa;
  --gold-dark: #9a3412;
  --gold-glow: rgba(224, 122, 95, 0.25);
  --gold-gradient: linear-gradient(135deg, #fed7aa 0%, #e07a5f 50%, #b45309 100%);
  --text-prime: #fff7ed;
}

/* Reset & Base Setup */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  font-size: 16px;
  scroll-behavior: smooth;
  background-color: var(--bg-prime);
  color: var(--text-prime);
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-serif);
  line-height: 1.65;
  overflow-x: hidden;
  position: relative;
  min-height: 100vh;
  background: radial-gradient(circle at 50% 0%, rgba(212, 175, 55, 0.05) 0%, transparent 60%),
              radial-gradient(circle at 10% 40%, rgba(94, 234, 212, 0.03) 0%, transparent 50%),
              radial-gradient(circle at 90% 80%, rgba(192, 132, 252, 0.04) 0%, transparent 50%),
              var(--bg-prime);
  transition: background-color 0.8s ease, color 0.8s ease;
}

::selection {
  background: var(--gold-prime);
  color: var(--bg-deep);
}

/* Accessibility Skip Link */
.skip-link {
  position: fixed;
  top: 1rem;
  left: 1rem;
  z-index: 10000;
  padding: 0.75rem 1.5rem;
  background: var(--gold-prime);
  color: var(--bg-deep);
  font-family: var(--font-sans);
  font-size: 0.875rem;
  font-weight: 700;
  text-decoration: none;
  border-radius: var(--radius-sm);
  transform: translateY(-200%);
  transition: transform 0.3s ease;
}

.skip-link:focus {
  transform: translateY(0);
}

/* Focus Visible */
:focus-visible {
  outline: 2px solid var(--gold-prime);
  outline-offset: 4px;
}

/* Screen reader announcement */
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border-width: 0;
}

/* SVG Definitions Holder */
.svg-defs {
  position: absolute;
  width: 0;
  height: 0;
  pointer-events: none;
  visibility: hidden;
}

/* Ambient Canvas Background */
#celestialCanvas {
  position: fixed;
  top: 0;
  left: 0;
  width: 100vw;
  height: 100vh;
  pointer-events: none;
  z-index: 0;
  opacity: 0.65;
  transition: opacity 1s ease;
}

/* Film Grain Overlay */
.grain-overlay {
  position: fixed;
  top: 0;
  left: 0;
  width: 100vw;
  height: 100vh;
  pointer-events: none;
  z-index: 9990;
  opacity: 0.035;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noiseFilter'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.8' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noiseFilter)'/%3E%3C/svg%3E");
}

/* Custom Interactive Cursor */
.custom-cursor {
  position: fixed;
  top: 0;
  left: 0;
  width: 32px;
  height: 32px;
  margin: -16px 0 0 -16px;
  border-radius: 50%;
  border: 1px solid var(--gold-prime);
  pointer-events: none;
  z-index: 9999;
  transition: transform 0.15s ease-out, width 0.3s ease, height 0.3s ease, background-color 0.3s ease, border-color 0.3s ease;
  transform: translate3d(-100px, -100px, 0);
  display: flex;
  align-items: center;
  justify-content: center;
}

.custom-cursor-dot {
  width: 4px;
  height: 4px;
  background: var(--gold-light);
  border-radius: 50%;
  box-shadow: 0 0 8px var(--gold-prime);
  transition: transform 0.2s ease;
}

.custom-cursor.active {
  width: 56px;
  height: 56px;
  margin: -28px 0 0 -28px;
  background-color: rgba(212, 175, 55, 0.12);
  border-color: var(--gold-light);
}

.custom-cursor.active .custom-cursor-dot {
  transform: scale(2);
}

.custom-cursor-text {
  position: absolute;
  font-family: var(--font-mono);
  font-size: 8px;
  letter-spacing: 1px;
  color: var(--gold-light);
  text-transform: uppercase;
  opacity: 0;
  transform: translateY(20px);
  transition: opacity 0.2s ease, transform 0.2s ease;
}

.custom-cursor.active .custom-cursor-text {
  opacity: 1;
  transform: translateY(32px);
}

@media (pointer: coarse) {
  .custom-cursor {
    display: none !important;
  }
}

/* ═══════════════════════════════════════════════════════════════════════════
   HEADER & NAVIGATION
   ═══════════════════════════════════════════════════════════════════════════ */
.masthead {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: var(--header-height);
  z-index: 1000;
  padding: 0 clamp(1.25rem, 4vw, 3.5rem);
  display: flex;
  align-items: center;
  justify-content: space-between;
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  background: linear-gradient(180deg, rgba(7, 8, 12, 0.85) 0%, rgba(7, 8, 12, 0.4) 70%, transparent 100%);
  border-bottom: 1px solid rgba(212, 175, 55, 0.08);
  transition: all 0.4s ease;
}

.masthead.scrolled {
  background: rgba(7, 8, 12, 0.92);
  border-bottom: 1px solid var(--border-subtle);
  height: 70px;
}

.brand-sigil-group {
  display: flex;
  align-items: center;
  gap: 1rem;
  text-decoration: none;
  color: inherit;
}

.brand-emblem {
  width: 38px;
  height: 38px;
  position: relative;
  display: grid;
  place-items: center;
}

.brand-emblem svg {
  width: 100%;
  height: 100%;
  animation: rotateSlow 40s linear infinite;
  transform-origin: center;
}

@keyframes rotateSlow {
  from { transform: rotate(0deg); }
  to { transform: rotate(360deg); }
}

.brand-wordmark {
  font-family: var(--font-display);
  font-size: clamp(1.25rem, 2.5vw, 1.6rem);
  font-weight: 700;
  letter-spacing: 0.25em;
  text-transform: uppercase;
  background: var(--gold-gradient);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  display: inline-block;
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 2rem;
  list-style: none;
}

@media (max-width: 900px) {
  .nav-links {
    display: none;
  }
}

.nav-item a {
  font-family: var(--font-sans);
  font-size: 0.8125rem;
  font-weight: 500;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--text-muted);
  text-decoration: none;
  position: relative;
  padding: 0.5rem 0;
  transition: color 0.3s ease;
}

.nav-item a::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  width: 0%;
  height: 1px;
  background: var(--gold-prime);
  transition: width 0.3s var(--ease-out-expo);
}

.nav-item a:hover {
  color: var(--gold-light);
}

.nav-item a:hover::after {
  width: 100%;
}

.header-controls {
  display: flex;
  align-items: center;
  gap: 1.25rem;
}

/* Atmosphere Theme Switcher */
.theme-selector-wrapper {
  display: flex;
  align-items: center;
  gap: 0.35rem;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid var(--border-subtle);
  padding: 4px 6px;
  border-radius: var(--radius-full);
}

.theme-btn {
  background: none;
  border: none;
  cursor: pointer;
  padding: 4px 8px;
  border-radius: var(--radius-full);
  font-family: var(--font-mono);
  font-size: 0.65rem;
  letter-spacing: 0.05em;
  color: var(--text-muted);
  transition: all 0.25s ease;
  text-transform: uppercase;
}

.theme-btn:hover {
  color: var(--gold-light);
}

.theme-btn.active {
  background: var(--gold-prime);
  color: var(--bg-deep);
  font-weight: 700;
}

/* Audio Control Button */
.audio-toggle-btn {
  background: rgba(212, 175, 55, 0.08);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-full);
  color: var(--gold-light);
  cursor: pointer;
  padding: 6px 12px;
  display: flex;
  align-items: center;
  gap: 6px;
  font-family: var(--font-mono);
  font-size: 0.7rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  transition: all 0.3s ease;
}

.audio-toggle-btn:hover {
  background: rgba(212, 175, 55, 0.2);
  border-color: var(--border-mid);
}

.sound-wave {
  display: flex;
  align-items: center;
  gap: 2px;
  height: 12px;
}

.sound-wave span {
  width: 2px;
  height: 100%;
  background: var(--gold-prime);
  border-radius: 1px;
  transform: scaleY(0.3);
  transition: transform 0.2s ease;
}

.audio-toggle-btn.playing .sound-wave span:nth-child(1) {
  animation: soundBars 0.8s ease-in-out infinite alternate;
}
.audio-toggle-btn.playing .sound-wave span:nth-child(2) {
  animation: soundBars 0.6s ease-in-out infinite alternate 0.2s;
}
.audio-toggle-btn.playing .sound-wave span:nth-child(3) {
  animation: soundBars 0.9s ease-in-out infinite alternate 0.4s;
}

@keyframes soundBars {
  0% { transform: scaleY(0.2); }
  100% { transform: scaleY(1); }
}

.btn-inscribe {
  background: var(--gold-gradient);
  color: var(--bg-deep);
  border: none;
  font-family: var(--font-sans);
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  padding: 0.65rem 1.4rem;
  border-radius: var(--radius-full);
  cursor: pointer;
  box-shadow: 0 4px 16px var(--gold-glow);
  transition: all 0.3s var(--ease-out-expo);
  text-decoration: none;
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
}

.btn-inscribe:hover {
  transform: translateY(-2px) scale(1.02);
  box-shadow: 0 8px 24px rgba(212, 175, 55, 0.45);
}

/* ═══════════════════════════════════════════════════════════════════════════
   HERO / PROSCENIUM SECTION
   ═══════════════════════════════════════════════════════════════════════════ */
.hero-section {
  position: relative;
  min-height: 100vh;
  padding: calc(var(--header-height) + 2rem) clamp(1.25rem, 5vw, 4rem) 4rem;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  text-align: center;
  z-index: 10;
  overflow: hidden;
}

.hero-backdrop-glow {
  position: absolute;
  top: 30%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: min(85vw, 900px);
  height: min(70vh, 600px);
  background: radial-gradient(ellipse at center, rgba(212, 175, 55, 0.14) 0%, rgba(94, 234, 212, 0.06) 40%, transparent 70%);
  filter: blur(60px);
  pointer-events: none;
  z-index: -1;
}

.hero-badge {
  display: inline-flex;
  align-items: center;
  gap: 0.75rem;
  padding: 0.4rem 1.25rem;
  background: rgba(212, 175, 55, 0.08);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-full);
  font-family: var(--font-mono);
  font-size: clamp(0.65rem, 1.2vw, 0.75rem);
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--gold-light);
  margin-bottom: 2rem;
  backdrop-filter: blur(8px);
}

.hero-badge-dot {
  width: 6px;
  height: 6px;
  background: var(--gold-prime);
  border-radius: 50%;
  box-shadow: 0 0 10px var(--gold-prime);
  animation: pulseDot 2s ease-in-out infinite;
}

@keyframes pulseDot {
  0%, 100% { opacity: 0.4; transform: scale(0.9); }
  50% { opacity: 1; transform: scale(1.3); }
}

/* Primary Visible Title — Exact Model Name Requirement */
.primary-title-h1 {
  font-family: var(--font-display);
  font-size: clamp(2.5rem, 7vw, 6.2rem);
  font-weight: 700;
  line-height: 1.05;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  margin-bottom: 1.5rem;
  background: linear-gradient(180deg, #ffffff 0%, #f4e4ba 40%, #d4af37 80%, #aa820a 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  filter: drop-shadow(0 4px 24px rgba(212, 175, 55, 0.25));
  max-width: 1200px;
}

.hero-subtitle {
  font-family: var(--font-serif);
  font-size: clamp(1.15rem, 2.2vw, 1.75rem);
  font-style: italic;
  font-weight: 300;
  color: var(--gold-light);
  max-width: 780px;
  margin: 0 auto 2.5rem;
  line-height: 1.5;
  text-wrap: balance;
}

.hero-description {
  font-family: var(--font-sans);
  font-size: clamp(0.875rem, 1.4vw, 1.05rem);
  color: var(--text-muted);
  max-width: 680px;
  margin: 0 auto 3rem;
  line-height: 1.8;
  font-weight: 300;
}

.hero-actions {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 1.5rem;
  flex-wrap: wrap;
  margin-bottom: 4rem;
}

.btn-secondary {
  background: transparent;
  color: var(--text-prime);
  border: 1px solid var(--border-mid);
  font-family: var(--font-sans);
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  padding: 0.65rem 1.6rem;
  border-radius: var(--radius-full);
  cursor: pointer;
  transition: all 0.3s ease;
  text-decoration: none;
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
}

.btn-secondary:hover {
  background: rgba(255, 255, 255, 0.05);
  border-color: var(--gold-light);
  color: var(--gold-light);
}

/* ═══════════════════════════════════════════════════════════════════════════
   QUAD-REALM HERO COMPOSITE (SURREAL LAYERED PORTALS)
   ═══════════════════════════════════════════════════════════════════════════ */
.hero-quad-composite {
  width: 100%;
  max-width: 1280px;
  margin: 0 auto;
  position: relative;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: clamp(0.75rem, 2vw, 1.5rem);
  perspective: 1200px;
  z-index: 5;
}

@media (max-width: 768px) {
  .hero-quad-composite {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 480px) {
  .hero-quad-composite {
    grid-template-columns: 1fr;
  }
}

.realm-preview-card {
  position: relative;
  height: clamp(320px, 45vh, 460px);
  border-radius: var(--radius-lg);
  overflow: hidden;
  cursor: pointer;
  border: 1px solid var(--border-subtle);
  background: var(--bg-surface);
  transition: transform 0.6s var(--ease-out-expo), border-color 0.4s ease, box-shadow 0.6s ease;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.4);
}

.realm-preview-card:hover {
  transform: translateY(-8px) scale(1.02);
  border-color: var(--border-bright);
  box-shadow: 0 20px 40px rgba(212, 175, 55, 0.25);
}

.realm-preview-card::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, rgba(7, 8, 12, 0.1) 0%, rgba(7, 8, 12, 0.4) 50%, rgba(7, 8, 12, 0.95) 100%);
  z-index: 2;
  pointer-events: none;
}

.realm-preview-card img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.8s var(--ease-out-expo), filter 0.6s ease;
  filter: brightness(0.85) contrast(1.1) saturate(1.05);
}

.realm-preview-card:hover img {
  transform: scale(1.1);
  filter: brightness(1) contrast(1.15) saturate(1.2);
}

.realm-card-content {
  position: absolute;
  bottom: 0;
  left: 0;
  width: 100%;
  padding: 1.5rem;
  z-index: 3;
  text-align: left;
}

.realm-card-roman {
  font-family: var(--font-display);
  font-size: 0.8rem;
  letter-spacing: 0.2em;
  color: var(--gold-prime);
  margin-bottom: 0.25rem;
}

.realm-card-title {
  font-family: var(--font-serif);
  font-size: 1.4rem;
  font-weight: 500;
  color: #fff;
  line-height: 1.2;
  margin-bottom: 0.35rem;
}

.realm-card-essence {
  font-family: var(--font-sans);
  font-size: 0.75rem;
  color: var(--text-muted);
  letter-spacing: 0.05em;
  font-weight: 300;
}

/* ═══════════════════════════════════════════════════════════════════════════
   MANIFESTO OF THE HOUSE
   ═══════════════════════════════════════════════════════════════════════════ */
.manifesto-section {
  position: relative;
  padding: clamp(5rem, 10vw, 8rem) clamp(1.25rem, 5vw, 4rem);
  max-width: var(--container-max);
  margin: 0 auto;
  z-index: 10;
}

.manifesto-grid {
  display: grid;
  grid-template-columns: 1fr 1.6fr;
  gap: clamp(2rem, 6vw, 5rem);
  align-items: center;
}

@media (max-width: 900px) {
  .manifesto-grid {
    grid-template-columns: 1fr;
  }
}

.manifesto-aside {
  border-left: 2px solid var(--gold-prime);
  padding-left: 1.5rem;
}

.manifesto-label {
  font-family: var(--font-mono);
  font-size: 0.75rem;
  letter-spacing: 0.25em;
  text-transform: uppercase;
  color: var(--gold-prime);
  margin-bottom: 1rem;
}

.manifesto-heading {
  font-family: var(--font-display);
  font-size: clamp(2rem, 4vw, 3.2rem);
  line-height: 1.15;
  color: var(--text-prime);
  margin-bottom: 1.5rem;
}

.manifesto-stats {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 1.5rem;
  margin-top: 2.5rem;
}

.stat-item-number {
  font-family: var(--font-display);
  font-size: 2.2rem;
  color: var(--gold-light);
  line-height: 1;
}

.stat-item-label {
  font-family: var(--font-sans);
  font-size: 0.75rem;
  color: var(--text-muted);
  letter-spacing: 0.1em;
  text-transform: uppercase;
  margin-top: 0.4rem;
}

.manifesto-body {
  font-size: clamp(1.15rem, 1.8vw, 1.35rem);
  line-height: 1.8;
  color: var(--text-muted);
  font-weight: 300;
}

.manifesto-body p {
  margin-bottom: 1.5rem;
}

.manifesto-body p strong {
  color: var(--gold-light);
  font-weight: 600;
}

.manifesto-pullquote {
  font-family: var(--font-serif);
  font-style: italic;
  font-size: clamp(1.4rem, 2.4vw, 1.85rem);
  color: var(--text-prime);
  border-top: 1px solid var(--border-subtle);
  border-bottom: 1px solid var(--border-subtle);
  padding: 2rem 0;
  margin: 2.5rem 0;
}

/* ═══════════════════════════════════════════════════════════════════════════
   THE FOUR REALMS — DEEP DIVE EXPEDITIONS (SURREAL LAYOUTS)
   ═══════════════════════════════════════════════════════════════════════════ */
.realms-container {
  position: relative;
  max-width: var(--container-max);
  margin: 0 auto;
  padding: 2rem clamp(1.25rem, 4vw, 3.5rem);
  z-index: 10;
}

.section-header-centered {
  text-align: center;
  margin-bottom: clamp(4rem, 8vw, 7rem);
}

.section-tag {
  font-family: var(--font-mono);
  font-size: 0.75rem;
  letter-spacing: 0.3em;
  text-transform: uppercase;
  color: var(--gold-prime);
  margin-bottom: 1rem;
}

.section-title {
  font-family: var(--font-display);
  font-size: clamp(2.2rem, 5vw, 3.8rem);
  color: var(--text-prime);
  line-height: 1.15;
  margin-bottom: 1rem;
}

.section-description {
  font-family: var(--font-serif);
  font-size: clamp(1.1rem, 1.8vw, 1.35rem);
  font-style: italic;
  color: var(--text-muted);
  max-width: 650px;
  margin: 0 auto;
}

/* Single Realm Showcase Block */
.realm-showcase {
  position: relative;
  margin-bottom: clamp(6rem, 12vw, 12rem);
  display: grid;
  grid-template-columns: 1.15fr 1fr;
  gap: clamp(2.5rem, 6vw, 6rem);
  align-items: center;
}

.realm-showcase.reversed {
  grid-template-columns: 1fr 1.15fr;
}

.realm-showcase.reversed .realm-art-wrapper {
  order: 2;
}

@media (max-width: 1024px) {
  .realm-showcase, .realm-showcase.reversed {
    grid-template-columns: 1fr;
    gap: 3rem;
  }
  .realm-showcase.reversed .realm-art-wrapper {
    order: 1;
  }
}

/* Custom Art Framings with SVG Clip-Paths & Parallax */
.realm-art-wrapper {
  position: relative;
  width: 100%;
}

.realm-frame {
  position: relative;
  width: 100%;
  aspect-ratio: 16 / 11;
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: 0 25px 60px rgba(0, 0, 0, 0.6);
  background: var(--bg-surface);
  transition: transform 0.5s ease;
}

/* Individual Shaped Clips */
.realm-frame.arch-clip {
  clip-path: url(#archClip);
  aspect-ratio: 1 / 1.15;
}

.realm-frame.shard-clip {
  clip-path: url(#shardClip);
  aspect-ratio: 1.2 / 1;
}

.realm-frame.river-clip {
  clip-path: url(#riverClip);
  aspect-ratio: 1.1 / 1;
}

.realm-frame.temple-clip {
  clip-path: url(#templeClip);
  aspect-ratio: 1.15 / 1;
}

.realm-frame img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.8s var(--ease-out-expo), filter 0.5s ease;
  filter: contrast(1.1) saturate(1.1);
}

.realm-art-wrapper:hover .realm-frame img {
  transform: scale(1.08);
}

/* Magnifying Loupe Overlay on Still Life */
.magnifier-lens {
  position: absolute;
  width: 140px;
  height: 140px;
  border-radius: 50%;
  border: 2px solid var(--gold-light);
  box-shadow: 0 0 25px rgba(212, 175, 55, 0.5), inset 0 0 15px rgba(255, 255, 255, 0.3);
  pointer-events: none;
  overflow: hidden;
  display: none;
  z-index: 15;
  background-repeat: no-repeat;
}

/* Floating Specimen Badge */
.art-floating-specimen {
  position: absolute;
  bottom: -20px;
  right: -20px;
  background: rgba(14, 17, 24, 0.85);
  border: 1px solid var(--border-mid);
  padding: 1rem 1.5rem;
  border-radius: var(--radius-md);
  backdrop-filter: blur(12px);
  z-index: 10;
  box-shadow: 0 15px 35px rgba(0, 0, 0, 0.5);
  max-width: 260px;
}

.art-floating-specimen .specimen-id {
  font-family: var(--font-mono);
  font-size: 0.7rem;
  color: var(--gold-prime);
  letter-spacing: 0.15em;
  margin-bottom: 0.35rem;
}

.art-floating-specimen .specimen-title {
  font-family: var(--font-serif);
  font-size: 0.95rem;
  color: var(--text-prime);
  font-style: italic;
}

/* Realm Text Details */
.realm-meta {
  display: flex;
  align-items: center;
  gap: 1.25rem;
  margin-bottom: 1rem;
}

.realm-index-num {
  font-family: var(--font-display);
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--gold-prime);
}

.realm-coords {
  font-family: var(--font-mono);
  font-size: 0.75rem;
  color: var(--text-dim);
  letter-spacing: 0.15em;
}

.realm-title-main {
  font-family: var(--font-display);
  font-size: clamp(2rem, 3.5vw, 3rem);
  line-height: 1.15;
  color: var(--text-prime);
  margin-bottom: 1.25rem;
}

.realm-tasting-notes {
  background: rgba(255, 255, 255, 0.02);
  border-left: 2px solid var(--gold-prime);
  padding: 1.25rem 1.5rem;
  margin-bottom: 1.75rem;
  border-radius: 0 var(--radius-md) var(--radius-md) 0;
}

.notes-label {
  font-family: var(--font-mono);
  font-size: 0.7rem;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--gold-light);
  margin-bottom: 0.5rem;
}

.notes-accord {
  font-family: var(--font-serif);
  font-size: 1.15rem;
  font-style: italic;
  color: var(--text-prime);
  line-height: 1.5;
}

.realm-body-text {
  font-family: var(--font-sans);
  font-size: 0.95rem;
  line-height: 1.8;
  color: var(--text-muted);
  margin-bottom: 2rem;
  font-weight: 300;
}

/* Interactive Accordion / Hotspot Triggers */
.realm-sensory-breakdown {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1rem;
  margin-bottom: 2.25rem;
}

@media (max-width: 600px) {
  .realm-sensory-breakdown {
    grid-template-columns: 1fr;
  }
}

.sensory-pillar {
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  padding: 1rem;
  border-radius: var(--radius-sm);
  transition: all 0.3s ease;
}

.sensory-pillar:hover {
  border-color: var(--gold-prime);
  background: var(--bg-surface-elevated);
}

.pillar-name {
  font-family: var(--font-mono);
  font-size: 0.65rem;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--gold-prime);
  margin-bottom: 0.25rem;
}

.pillar-val {
  font-family: var(--font-serif);
  font-size: 1rem;
  color: var(--text-prime);
}

.realm-action-row {
  display: flex;
  align-items: center;
  gap: 1rem;
  flex-wrap: wrap;
}

.btn-realm-explore {
  background: rgba(212, 175, 55, 0.1);
  border: 1px solid var(--border-mid);
  color: var(--gold-light);
  padding: 0.65rem 1.4rem;
  border-radius: var(--radius-full);
  font-family: var(--font-sans);
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  cursor: pointer;
  transition: all 0.3s ease;
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
}

.btn-realm-explore:hover {
  background: var(--gold-prime);
  color: var(--bg-deep);
  border-color: var(--gold-prime);
  transform: translateY(-2px);
}

.btn-sound-trigger {
  background: transparent;
  border: 1px solid rgba(255, 255, 255, 0.1);
  color: var(--text-muted);
  width: 38px;
  height: 38px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  cursor: pointer;
  transition: all 0.25s ease;
}

.btn-sound-trigger:hover {
  border-color: var(--gold-prime);
  color: var(--gold-light);
}

/* ═══════════════════════════════════════════════════════════════════════════
   THE SENSORY SYNTHESIZER / INTERACTIVE ALCHEMICAL LAB
   ═══════════════════════════════════════════════════════════════════════════ */
.synthesizer-section {
  position: relative;
  padding: clamp(5rem, 10vw, 8rem) clamp(1.25rem, 5vw, 4rem);
  max-width: var(--container-max);
  margin: 0 auto;
  z-index: 10;
}

.synth-console {
  background: radial-gradient(circle at 50% 0%, rgba(212, 175, 55, 0.08) 0%, rgba(14, 17, 24, 0.95) 70%);
  border: 1px solid var(--border-mid);
  border-radius: var(--radius-lg);
  padding: clamp(2rem, 5vw, 4rem);
  box-shadow: 0 30px 80px rgba(0, 0, 0, 0.7);
  display: grid;
  grid-template-columns: 1.2fr 1fr;
  gap: clamp(2.5rem, 5vw, 5rem);
  align-items: center;
}

@media (max-width: 950px) {
  .synth-console {
    grid-template-columns: 1fr;
  }
}

.synth-sliders-group {
  display: flex;
  flex-direction: column;
  gap: 2rem;
}

.slider-unit {
  position: relative;
}

.slider-label-row {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  margin-bottom: 0.6rem;
}

.slider-name {
  font-family: var(--font-serif);
  font-size: 1.15rem;
  color: var(--text-prime);
}

.slider-tag {
  font-family: var(--font-mono);
  font-size: 0.75rem;
  color: var(--gold-prime);
}

.slider-track-wrap {
  position: relative;
  display: flex;
  align-items: center;
}

input[type="range"].elysian-range {
  -webkit-appearance: none;
  width: 100%;
  height: 4px;
  background: rgba(255, 255, 255, 0.1);
  border-radius: 2px;
  outline: none;
  cursor: pointer;
  transition: background 0.3s ease;
}

input[type="range"].elysian-range::-webkit-slider-thumb {
  -webkit-appearance: none;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  background: var(--gold-gradient);
  border: 2px solid var(--bg-deep);
  box-shadow: 0 0 12px var(--gold-prime);
  cursor: pointer;
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

input[type="range"].elysian-range::-webkit-slider-thumb:hover {
  transform: scale(1.25);
  box-shadow: 0 0 20px var(--gold-light);
}

/* Generative Sigil Canvas / Display Output */
.synth-sigil-display {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  background: rgba(7, 8, 12, 0.6);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
  padding: 2.5rem 2rem;
  position: relative;
}

#sigilCanvas {
  width: 220px;
  height: 220px;
  margin-bottom: 1.5rem;
}

.generated-accord-title {
  font-family: var(--font-display);
  font-size: 1.5rem;
  color: var(--gold-light);
  margin-bottom: 0.5rem;
}

.generated-accord-desc {
  font-family: var(--font-serif);
  font-size: 1.05rem;
  font-style: italic;
  color: var(--text-muted);
  line-height: 1.5;
  margin-bottom: 1.5rem;
  min-height: 3rem;
}

.btn-harmonize-play {
  background: var(--gold-gradient);
  color: var(--bg-deep);
  border: none;
  padding: 0.75rem 1.8rem;
  border-radius: var(--radius-full);
  font-family: var(--font-sans);
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  cursor: pointer;
  box-shadow: 0 4px 20px var(--gold-glow);
  transition: all 0.3s ease;
  display: inline-flex;
  align-items: center;
  gap: 0.6rem;
}

.btn-harmonize-play:hover {
  transform: scale(1.04);
  box-shadow: 0 8px 30px rgba(212, 175, 55, 0.5);
}

/* ═══════════════════════════════════════════════════════════════════════════
   THE COMPARATIVE ATLAS MATRIX
   ═══════════════════════════════════════════════════════════════════════════ */
.atlas-section {
  position: relative;
  max-width: var(--container-max);
  margin: 0 auto;
  padding: clamp(4rem, 8vw, 7rem) clamp(1.25rem, 4vw, 3.5rem);
  z-index: 10;
}

.matrix-table-wrap {
  width: 100%;
  overflow-x: auto;
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
  background: var(--bg-surface);
  box-shadow: 0 15px 40px rgba(0, 0, 0, 0.5);
}

.matrix-table {
  width: 100%;
  border-collapse: collapse;
  text-align: left;
  min-width: 700px;
}

.matrix-table th, .matrix-table td {
  padding: 1.25rem 1.75rem;
  border-bottom: 1px solid rgba(212, 175, 55, 0.08);
}

.matrix-table th {
  background: rgba(14, 17, 24, 0.9);
  font-family: var(--font-mono);
  font-size: 0.75rem;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--gold-prime);
}

.matrix-table td {
  font-family: var(--font-serif);
  font-size: 1.05rem;
  color: var(--text-prime);
}

.matrix-table tr:last-child td {
  border-bottom: none;
}

.matrix-table tr:hover td {
  background: rgba(212, 175, 55, 0.03);
}

.matrix-realm-tag {
  font-family: var(--font-display);
  font-weight: 700;
  color: var(--gold-light);
}

/* ═══════════════════════════════════════════════════════════════════════════
   THE PRIVATE DOSSIER / RESERVATION DIALOG
   ═══════════════════════════════════════════════════════════════════════════ */
dialog.elysian-dialog {
  border: 1px solid var(--border-bright);
  background: #080a0f;
  color: var(--text-prime);
  border-radius: var(--radius-lg);
  padding: clamp(2rem, 5vw, 3.5rem);
  max-width: 680px;
  width: 90vw;
  margin: auto;
  box-shadow: 0 30px 90px rgba(0, 0, 0, 0.9), 0 0 40px var(--gold-glow);
  z-index: 10000;
  overflow-y: auto;
  max-height: 90vh;
}

dialog.elysian-dialog::backdrop {
  background: rgba(3, 4, 7, 0.85);
  backdrop-filter: blur(12px);
}

.dialog-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  margin-bottom: 2rem;
  border-bottom: 1px solid var(--border-subtle);
  padding-bottom: 1.25rem;
}

.dialog-title {
  font-family: var(--font-display);
  font-size: clamp(1.6rem, 3vw, 2.2rem);
  color: var(--gold-light);
}

.btn-dialog-close {
  background: none;
  border: 1px solid var(--border-subtle);
  color: var(--text-muted);
  width: 36px;
  height: 36px;
  border-radius: 50%;
  cursor: pointer;
  font-size: 1.25rem;
  display: grid;
  place-items: center;
  transition: all 0.2s ease;
}

.btn-dialog-close:hover {
  border-color: var(--gold-prime);
  color: var(--gold-light);
}

.dossier-form {
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

.form-field {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.form-label {
  font-family: var(--font-mono);
  font-size: 0.75rem;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--gold-prime);
}

.form-input, .form-select, .form-textarea {
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid var(--border-subtle);
  padding: 0.85rem 1.2rem;
  border-radius: var(--radius-sm);
  color: var(--text-prime);
  font-family: var(--font-sans);
  font-size: 0.95rem;
  outline: none;
  transition: border-color 0.3s ease;
}

.form-input:focus, .form-select:focus, .form-textarea:focus {
  border-color: var(--gold-prime);
}

/* Interactive Wax Seal Stamp */
.wax-seal-wrapper {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 1rem;
  padding: 1.5rem;
  background: rgba(255, 255, 255, 0.02);
  border: 1px dashed var(--border-mid);
  border-radius: var(--radius-md);
  margin-top: 0.5rem;
  text-align: center;
}

.wax-seal-btn {
  width: 80px;
  height: 80px;
  border-radius: 50%;
  background: radial-gradient(circle at 30% 30%, #ffd700, #b8860b, #6b4e07);
  border: 2px solid #fff5cc;
  box-shadow: 0 6px 20px rgba(212, 175, 55, 0.4);
  cursor: pointer;
  display: grid;
  place-items: center;
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.wax-seal-btn:hover {
  transform: scale(1.08);
  box-shadow: 0 10px 30px rgba(212, 175, 55, 0.6);
}

.wax-seal-btn.sealed {
  animation: sealPress 0.5s ease-out;
}

@keyframes sealPress {
  0% { transform: scale(1.2); }
  50% { transform: scale(0.9); }
  100% { transform: scale(1); }
}

.confirmation-card {
  padding: 1.5rem;
  border-radius: var(--radius-md);
  background: rgba(212, 175, 55, 0.08);
  border: 1px solid var(--border-bright);
  text-align: center;
  display: none;
}

.confirmation-card.show {
  display: block;
}

/* ═══════════════════════════════════════════════════════════════════════════
   FOOTER & CURATION COLOPHON
   ═══════════════════════════════════════════════════════════════════════════ */
.colophon-footer {
  position: relative;
  background: var(--bg-deep);
  border-top: 1px solid var(--border-subtle);
  padding: clamp(4rem, 8vw, 6rem) clamp(1.25rem, 5vw, 4rem) 3rem;
  z-index: 10;
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr repeat(3, 1fr);
  gap: clamp(2rem, 4vw, 4rem);
  max-width: var(--container-max);
  margin: 0 auto 4rem;
}

@media (max-width: 900px) {
  .footer-grid {
    grid-template-columns: 1fr 1fr;
  }
}

@media (max-width: 550px) {
  .footer-grid {
    grid-template-columns: 1fr;
  }
}

.footer-brand .brand-wordmark {
  margin-bottom: 1rem;
}

.footer-tagline {
  font-family: var(--font-serif);
  font-style: italic;
  font-size: 1.15rem;
  color: var(--text-muted);
  max-width: 320px;
  line-height: 1.6;
}

.footer-column-title {
  font-family: var(--font-mono);
  font-size: 0.75rem;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--gold-prime);
  margin-bottom: 1.25rem;
}

.footer-links {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.footer-links a {
  font-family: var(--font-sans);
  font-size: 0.85rem;
  color: var(--text-muted);
  text-decoration: none;
  transition: color 0.25s ease;
}

.footer-links a:hover {
  color: var(--gold-light);
}

.footer-bottom {
  max-width: var(--container-max);
  margin: 0 auto;
  border-top: 1px solid rgba(255, 255, 255, 0.05);
  padding-top: 2rem;
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 1rem;
}

.footer-copyright {
  font-family: var(--font-sans);
  font-size: 0.75rem;
  color: var(--text-dim);
}

.footer-model-badge {
  font-family: var(--font-mono);
  font-size: 0.7rem;
  color: var(--gold-prime);
  letter-spacing: 0.1em;
}

/* ═══════════════════════════════════════════════════════════════════════════
   RESPONSIVE & ACCESSIBILITY OVERRIDES
   ═══════════════════════════════════════════════════════════════════════════ */
@media (max-width: 25rem) {
  :root {
    --header-height: 72px;
  }
  .primary-title-h1 {
    font-size: 2.2rem;
  }
  .manifesto-stats {
    grid-template-columns: 1fr;
  }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
  #celestialCanvas {
    display: none;
  }
}

